import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import * as api from 'products/data_catalog/frontend/generated/api'

import type { PaginatedDataCatalogMetricListApi } from '../../data_catalog/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface biCatalogPickerLogicValues {
    error: boolean
    isOpen: boolean
    metrics: Awaited<ReturnType<typeof api.dataCatalogMetricsList>> | null
    metricsLoading: boolean
    page: number
    search: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface biCatalogPickerLogicActions {
    close: () => {
        value: true
    }
    loadMetrics: (_: void) => void
    loadMetricsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadMetricsSuccess: (
        metrics: PaginatedDataCatalogMetricListApi,
        payload?: void
    ) => {
        metrics: PaginatedDataCatalogMetricListApi
        payload?: void
    }
    open: () => {
        value: true
    }
    setPage: (page: number) => {
        page: number
    }
    setSearch: (search: string) => {
        search: string
    }
}

export type biCatalogPickerLogicType = MakeLogicType<biCatalogPickerLogicValues, biCatalogPickerLogicActions>

export const biCatalogPickerLogic = kea<biCatalogPickerLogicType>([
    path(['products', 'business_intelligence', 'biCatalogPickerLogic']),
    actions({
        open: true,
        close: true,
        setSearch: (search: string) => ({ search }),
        setPage: (page: number) => ({ page }),
    }),
    reducers({
        isOpen: [false, { open: () => true, close: () => false }],
        search: ['', { setSearch: (_, { search }) => search, open: () => '' }],
        page: [0, { setPage: (_, { page }) => page, setSearch: () => 0, open: () => 0 }],
        error: [false, { loadMetrics: () => false, loadMetricsFailure: () => true }],
    }),
    loaders(({ values }) => ({
        metrics: [
            null as Awaited<ReturnType<typeof api.dataCatalogMetricsList>> | null,
            {
                loadMetrics: async (_: void, breakpoint) => {
                    await breakpoint(250)
                    const response = await api
                        .dataCatalogMetricsList(String(teamLogic.values.currentTeamId), {
                            search: values.search.trim() || undefined,
                            limit: 20,
                            offset: values.page * 20,
                        })
                        .catch((error) => {
                            breakpoint()
                            throw error
                        })
                    breakpoint()
                    return response
                },
            },
        ],
    })),
    listeners(({ actions }) => ({
        open: () => actions.loadMetrics(),
        setSearch: () => actions.loadMetrics(),
        setPage: () => actions.loadMetrics(),
    })),
])
